def run_regression():
    root = Path(__file__).resolve().parents[1]
    checks = 0
    for sym, (oldrel, newrel, oldhash, _) in SPLIT_SYMBOLS.items():
        tree = ast.parse((root/newrel).read_text(encoding='utf-8'))
        nodes = [n for n in tree.body if isinstance(n,ast.FunctionDef) and n.name == sym]
        assert len(nodes) == 1, ('missing native body', sym)
        assert sha256(ast.dump(nodes[0],include_attributes=False).encode()).hexdigest() == oldhash, ('authored code changed',sym)
        source = (root/oldrel).read_text(encoding='utf-8')
        assert '_sb410_bind(' in source and f'{sym} = _sb410_bind(' in source, ('unbound facade',sym)
        checks += 3
    from core.legacy_function_binding_v410 import bind_legacy_function_v410
    def probe(x):
        return mutable_probe_counter + x
    first = {'__name__':'validation.v4100', 'mutable_probe_counter': 3}
    bound = bind_legacy_function_v410(probe, first)
    assert bound(10)==13
    first['mutable_probe_counter']=99
    assert bound(1)==100 and bound.__globals__ is first
    checks+=3
    import server
    from core.bootstrap_economy_professions import VERSION
    assert VERSION in ('4.10.0','4.20.0','4.21.0','4.21.1','5.00.0','5.00.1','6.00.0','6.00.1')
    assert len(server.QUESTS)== (3861 if VERSION == '6.00.1' else 2901 if VERSION in ('5.00.0','5.00.1','6.00.0','6.00.1') else 2701) and len(server.CLASS_SKILLS)==14
    from config.balance import ALL_PROGRESS_XP_REQUIREMENT_MULTIPLIER_V3310
    assert ALL_PROGRESS_XP_REQUIREMENT_MULTIPLIER_V3310==10
    checks+=4
    return checks

if __name__ == '__main__':
    print(f'MODULARYZACJA 4.10.0: {run_regression()} checks PASS')
